const $=selector=>document.querySelector(selector);
let csrf='',draft={},saved={},catalog=[],defaults={},sections=[],sectionNames={},selected='about',dirty=false,previewTimer,toastTimer;
const collectionLabels={color:'Color & blonding',extensions:'Extensions',cuts:'Cuts & styling',gallery:'Portfolio photos',steps:'New client steps',faqs:'Questions & answers'};
const collectionGroups={services:['color','extensions','cuts'],portfolio:['gallery'],newClient:['steps'],faq:['faqs']};
const fieldLabels={title:'Name / heading',description:'Description',price:'Price',src:'Photo',alt:'Photo description',caption:'Caption',url:'Link to original post',question:'Question',answer:'Answer'};
const emptyItems={color:{title:'New service',description:'Describe this service.',price:'Custom quote'},extensions:{title:'New service',description:'Describe this service.',price:'Custom quote'},cuts:{title:'New service',description:'Describe this service.',price:'Custom quote'},gallery:{src:'assets/lived-in-blonde.jpg',alt:'Hair by Halli Miller',caption:'New look',url:'https://www.instagram.com/hairby.hallij/'},steps:{title:'New step',description:'Describe this step.'},faqs:{question:'New question',answer:'Add your answer.'}};
function node(tag,text,className){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element;}
function toast(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4500);}
async function api(url,options={}){const response=await fetch(url,{...options,headers:{'X-CSRF-Token':csrf,...options.headers}});const data=await response.json();if(!response.ok){if(response.status===401&&url!=='/api/admin/login'){showLogin();}throw Error(data.error||'Something went wrong. Please try again.');}return data;}
function markDirty(){dirty=true;$('#save-status').textContent='Unsaved changes';clearTimeout(previewTimer);previewTimer=setTimeout(updatePreview,120);}
function updatePreview(){const frame=$('#preview');frame.contentWindow?.postMessage({type:'halli:preview',config:draft},location.origin);}
function showLogin(){$('#editor').hidden=true;$('#login').hidden=false;$('#password').value='';}
function showEditor(){$('#login').hidden=true;$('#editor').hidden=false;$('#preview').src='/?editor=1';}
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;$('#login-error').textContent='';try{const result=await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#password').value})});csrf=result.csrf;$('#password').value='';showEditor();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}});
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==$('#preview').contentWindow)return;if(event.data?.type==='halli:error'){toast(event.data.message);return;}if(event.data?.type!=='halli:ready')return;catalog=event.data.catalog;defaults=event.data.collections;sections=event.data.sections;sectionNames=event.data.sectionNames;if(!dirty){draft=structuredClone(event.data.config);saved=structuredClone(draft);}buildNavigation();render();updatePreview();});
function buildNavigation(){const navigation=$('#sections');navigation.replaceChildren();for(const[id,label]of Object.entries({...sectionNames,appearance:'Colors & fonts',layout:'Section order'})){const button=node('button',label);button.setAttribute('aria-current',String(selected===id));button.addEventListener('click',()=>{selected=id;buildNavigation();render();$('#preview').contentWindow?.postMessage({type:'halli:focus',section:id},location.origin);});navigation.append(button);}}
function control(label,value,onChange,{long=false,type='text',help='',options}={}){const wrapper=node('div',undefined,'field');const id='field-'+Math.random().toString(36).slice(2);const text=node('label',label);text.htmlFor=id;const input=node(options?'select':long?'textarea':'input');input.id=id;if(input.tagName==='INPUT')input.type=type;if(options)for(const [v,l]of options) {const option=node('option',l);option.value=v;input.append(option);}input.value=value??'';input.addEventListener('input',()=>{onChange(input.value);markDirty();});wrapper.append(text,input);if(help)wrapper.append(node('small',help));return wrapper;}
function imageControl(label,value,onChange,{alt='',fit='',position=''}={},onMeta){const wrapper=node('div',undefined,'field');wrapper.append(node('label',label));const image=node('img');image.src=value;image.alt=alt;wrapper.append(image);const uploadLabel=node('label','Choose a new photo','upload-label');const file=node('input');file.type='file';file.accept='image/jpeg,image/png,image/webp,image/gif';file.hidden=true;uploadLabel.append(file);file.addEventListener('change',async()=>{if(!file.files[0])return;const chosen=file.files[0];if(chosen.size>10*1024*1024){toast('Please choose a photo smaller than 10 MB.');return;}uploadLabel.classList.add('busy');try{const result=await api('/api/admin/upload',{method:'POST',headers:{'Content-Type':chosen.type},body:chosen});onChange(result.url);image.src=result.url;urlInput.querySelector('input').value=result.url;markDirty();toast('Photo uploaded. Save changes when you’re ready.');}catch(error){toast(error.message);}finally{uploadLabel.classList.remove('busy');file.value='';}});wrapper.append(uploadLabel);const urlInput=control('Photo URL',value,value=>{onChange(value);image.src=value;},{help:'Choose a photo above, or paste a link to an image.'});wrapper.append(urlInput);if(onMeta){wrapper.append(control('Photo description',alt,value=>onMeta('alt',value)));const options=node('div',undefined,'image-options');options.append(control('Photo fit',fit||'',value=>onMeta('fit',value),{options:[['','Natural / default'],['contain','Show entire photo'],['cover','Fill the frame']]}),control('Photo focus',position||'',value=>onMeta('position',value),{options:[['','Center / default'],['center top','Top'],['center','Center'],['center bottom','Bottom'],['left center','Left'],['right center','Right']]}));wrapper.append(options);}return wrapper;}
function render(){const heading=$('#edit-heading');heading.replaceChildren(node('h1',sectionNames[selected]||({appearance:'Colors & fonts',layout:'Section order'}[selected])));heading.append(node('p',selected==='layout'?'Move sections into the order you like.':selected==='appearance'?'Choose your colors and fonts. Use the text size control to keep everything easy to read.':'Edit the words, links, and photos below. Your preview updates as you type.'));const target=$('#fields');target.replaceChildren();draft.fields??={};draft.theme??={};draft.hidden??={};draft.collections??={};
if(sections.some(s=>s.id===selected)){const wrapper=node('div',undefined,'visibility');const label=node('label');const checkbox=node('input');checkbox.type='checkbox';checkbox.checked=!draft.hidden[selected];checkbox.addEventListener('change',()=>{draft.hidden[selected]=!checkbox.checked;markDirty();});label.append(checkbox,document.createTextNode('Show this section on the website'));wrapper.append(label);target.append(wrapper);}
if(selected==='appearance'){const colors={paper:['Page background','#f8f5ef'],cream:['Section background','#eee8df'],ink:['Headings & dark sections','#38291f'],muted:['Body text','#796b61'],line:['Lines & borders','#d8cec2']};for(const[key,[label,value]]of Object.entries(colors))target.append(control(label,draft.theme[key]||value,value=>draft.theme[key]=value,{type:'color'}));const fonts=[["'Cormorant Garamond', Georgia, serif",'Elegant serif (current)'],['Georgia, serif','Classic serif'],["'DM Sans', Arial, sans-serif",'Modern sans serif'],['Arial, sans-serif','Simple sans serif'],['Verdana, sans-serif','Wide sans serif']];target.append(control('Heading font',draft.theme.headingFont||fonts[0][0],v=>draft.theme.headingFont=v,{options:fonts}),control('Body font',draft.theme.bodyFont||fonts[2][0],v=>draft.theme.bodyFont=v,{options:fonts}),control('Text size',draft.theme.textScale??1,v=>draft.theme.textScale=Number(v),{options:[['0.9','Slightly smaller'],['1','Comfortable (current)'],['1.1','Larger'],['1.2','Extra large'],['1.3','Very large']]}));const reset=node('button','Reset colors & fonts');reset.addEventListener('click',()=>{draft.theme={};markDirty();render();});target.append(reset);return;}
if(selected==='layout'){const order=[...new Set([...(draft.order||[]),...sections.map(s=>s.id)])];order.forEach((id,index)=>{const item=node('div',undefined,'order-item');item.append(node('span',sectionNames[id]));for(const[direction,label]of [[-1,'↑'],[1,'↓']]){const button=node('button',label);button.setAttribute('aria-label',`Move ${sectionNames[id]} ${direction===-1?'up':'down'}`);button.disabled=index+direction<0||index+direction>=order.length;button.addEventListener('click',()=>{[order[index],order[index+direction]]=[order[index+direction],order[index]];draft.order=order;markDirty();render();});item.append(button);}target.append(item);});return;}
const entries=catalog.filter(f=>f.group===selected);for(const kind of ['text','url','image']){const items=entries.filter(f=>f.kind===kind);if(!items.length)continue;target.append(node('p',{text:'WORDS & HEADINGS',url:'BUTTONS & LINKS',image:'PHOTOS'}[kind],'group-label'));for(const field of items){const value=draft.fields[field.id]??field.value;if(kind==='image')target.append(imageControl(field.label,value,v=>draft.fields[field.id]=v,{alt:draft.fields[field.id+'-alt']??field.alt,fit:draft.fields[field.id+'-fit'],position:draft.fields[field.id+'-position']},(key,value)=>draft.fields[field.id+'-'+key]=value));else target.append(control(field.label,value,v=>draft.fields[field.id]=v,{long:field.long,help:kind==='url'?'Use a full web address or a section link such as #services.':''}));}}
for(const key of collectionGroups[selected]||[])renderCollection(key,target);
}
function renderCollection(key,target){target.append(node('p',collectionLabels[key].toUpperCase(),'group-label'));const items=draft.collections[key]??structuredClone(defaults[key]);function update(){draft.collections[key]=items;markDirty();}
items.forEach((item,index)=>{const card=node('div',undefined,'item-card');const toolbar=node('div',undefined,'item-toolbar');toolbar.append(node('strong',`${index+1}. ${item.title||item.caption||item.question||'Item'}`));for(const[step,label]of [[-1,'↑'],[1,'↓']]){const button=node('button',label);button.setAttribute('aria-label',`Move item ${index+1} ${step<0?'up':'down'}`);button.disabled=index+step<0||index+step>=items.length;button.addEventListener('click',()=>{[items[index],items[index+step]]=[items[index+step],items[index]];update();render();});toolbar.append(button);}const remove=node('button','Remove','remove');remove.addEventListener('click',()=>{items.splice(index,1);update();render();});toolbar.append(remove);card.append(toolbar);
for(const field of Object.keys(emptyItems[key])){if(field==='alt'&&key==='gallery')continue;if(field==='src')card.append(imageControl('Photo',item.src,v=>{item.src=v;update();},{alt:item.alt,fit:item.fit,position:item.position},(meta,value)=>{item[meta]=value;update();}));else card.append(control(fieldLabels[field],item[field],value=>{item[field]=value;update();},{long:['description','answer'].includes(field)}));}target.append(card);});const add=node('button',`+ Add ${key==='gallery'?'photo':key==='faqs'?'question':key==='steps'?'step':'service'}`,'add-button');add.addEventListener('click',()=>{items.push(structuredClone(emptyItems[key]));update();render();});target.append(add);}
$('#save').addEventListener('click',async()=>{const button=$('#save');button.disabled=true;const saving=structuredClone(draft);$('#save-status').textContent='Saving…';try{const result=await api('/api/admin/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(saving)});saved=structuredClone(result.content);if(JSON.stringify(draft)===JSON.stringify(saving)){draft=structuredClone(result.content);dirty=false;$('#save-status').textContent='All changes saved';}else{$('#save-status').textContent='Unsaved changes';}toast('Your website is updated.');}catch(error){$('#save-status').textContent='Changes not saved';toast(error.message);}finally{button.disabled=false;}});
$('#logout').addEventListener('click',async()=>{if(dirty&&!confirm('You have unsaved changes. Sign out without saving them?'))return;try{await api('/api/admin/logout',{method:'POST'});dirty=false;draft={};saved={};$('#preview').src='about:blank';showLogin();}catch(error){toast(error.message);}});
$('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=node('a');link.href=url;link.download=`halli-website-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);toast('Backup downloaded.');});
$('#import').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('This backup is too large.');const value=JSON.parse(await file.text());if(value.version!==1||!value.fields||!value.collections||typeof value.fields!=='object'||Object.values(value.fields).some(v=>typeof v!=='string'))throw Error('Please choose a Halli website backup file.');draft=value;markDirty();render();toast('Backup loaded into the preview. Save changes to apply it.');}catch(error){toast(error.message);}finally{event.target.value='';}});
for(const mode of ['desktop','mobile'])$('#'+mode).addEventListener('click',()=>{$('#preview').classList.toggle('mobile',mode==='mobile');$('#desktop').setAttribute('aria-pressed',String(mode==='desktop'));$('#mobile').setAttribute('aria-pressed',String(mode==='mobile'));});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
api('/api/admin/session').then(data=>{if(data.authenticated){csrf=data.csrf;showEditor();}else showLogin();}).catch(error=>{$('#login-error').textContent=error.message;});
function resizePreview(){const wrap=$('.preview-wrap');if(!wrap.clientWidth||!wrap.clientHeight)return;const frame=$('#preview');const width=frame.classList.contains('mobile')?390:1280;const scale=Math.min(1,wrap.clientWidth/width);frame.style.width=width+'px';frame.style.height=wrap.clientHeight/scale+'px';frame.style.transform=`scale(${scale})`;frame.style.marginLeft=Math.max(0,(wrap.clientWidth-width*scale)/2)+'px';}
new ResizeObserver(resizePreview).observe($('.preview-wrap'));
$('#desktop').addEventListener('click',resizePreview);$('#mobile').addEventListener('click',resizePreview);
